package com.bank.token;

import java.util.Arrays;
import java.util.logging.Logger;

public class TokenDemo {
    private static final Logger log = Logger.getLogger(TokenDemo.class.getName());

    public static void main(String[] args) {
        int[] pool = {3, 4, -1, 1};   // negatives/junk allowed
        log.info("Token pool: " + Arrays.toString(pool));

        TokenDispenser dispenser = new TokenDispenser();
        int next = dispenser.nextAvailableToken(pool);

        log.info("Next token to issue: " + next);
    }
}
