package com.bank.token;

public class TokenDispenser {

    public int nextAvailableToken(int[] pool) {
        int i = 0, n = pool.length;
        while (i < n) {
            int v = pool[i];
            // Only place in-range positives; skip junk and already-home values.
            if (v > 0 && v <= n && pool[i] != pool[v - 1]) {
                int tmp = pool[i]; pool[i] = pool[v - 1]; pool[v - 1] = tmp;
            } else {
                i++;
            }
        }
        for (int idx = 0; idx < n; idx++) {
            if (pool[idx] != idx + 1) return idx + 1;   // first empty home
        }
        return n + 1;   // 1..n all present
    }
}
